WITH valid_accounts AS (SELECT *, CASE WHEN status = 'CLOSED' THEN 1 ELSE 0 END AS is_closed FROM accounts WHERE account_type = 'CREDIT' AND balance <= 68000), accounts_stats AS (SELECT status, ROUND((100 * SUM(CASE WHEN account_type = 'CREDIT' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_credit, COUNT(CASE WHEN account_type = 'LOAN' THEN 1 END) AS loan_count FROM valid_accounts GROUP BY status) SELECT status, pct_credit FROM accounts_stats
